installer-gui-script.script:
function checks() {
  var r = system.run('/usr/bin/pgrep', '-x', 'After Effects');
  if (r === 0) { my.result.title = 'Quit After Effects'; my.result.message = 'After Effects is running. Quit it, then run this installer again.'; my.result.type = 'Fatal'; return false; }
  return true;
}
